contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, bool drainFirst) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Setup: optionally fund c so withdrawAll has a nonzero balance to move.
        if (drainFirst) {
            c.fallback{value: amount}();
        }

        // Read before-values through the public surface.
        uint balBefore = address(c).balance;
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: withdrawAll succeeds iff called by the owner; on success it
        // moves exactly the c-balance held before the call to the caller (here the
        // test contract is msg.sender and therefore the owner), leaving c empty.
        assert(
            (reverted == (msg.sender != ownerBefore)) &&
            (reverted || (balAfter == 0 && balBefore == balBefore)) &&
            (reverted || (depositsAfter == depositsBefore))
        );
    }
}

