contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0), "zero caller");

        // Read owner and balance before.
        address owner_ = c.owner();
        uint balBefore = address(c).balance;

        // The only way to make msg.sender differ from owner is to use a call from another address,
        // but in this test environment msg.sender is always this contract.  
        // We cannot change msg.sender, so we drive withdrawAll as this contract.
        bool reverted = false;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: withdrawAll is owner-only.
        // If the caller is not the owner, it must revert.
        // If the caller is the owner, either it reverts (e.g. transfer fails) or it completes
        // and the entire balance is sent to the owner, leaving the contract with zero balance.
        if (caller != owner_) {
            assert(reverted);
        } else {
            // Owner call: if it succeeded, balance must be zero and balance decreased by exactly the previous balance.
            // If it reverted, the balance must be unchanged.
            assert(reverted ? balAfter == balBefore : (balAfter == 0 && balBefore >= balAfter));
        }
    }

    receive() external payable {}
}

